function normalizePhone(v){let p=String(v||'').replace(/\D/g,'');if(p.startsWith('00'))p=p.slice(2);if(/^0\d{9}$/.test(p))p='256'+p.slice(1);return p;}
const history=$('Load campaign history').all().map(x=>x.json);
const prospects=new Map($input.all().map(x=>[x.json.id,x.json]));
const key=r=>(r.outreach_cycle||'legacy')+'|'+normalizePhone(r.phone_number);
const blocked=new Set(history.filter(r=>['sent','sent_duplicate','followed_up','replied','sending','skipped_duplicate'].includes(r.queue_status)).map(key));
const groups=new Map();
for(const item of $('Load approved B2B campaign rows').all()){
 const r=item.json,p=prospects.get(r.prospect_id),phone=normalizePhone(r.phone_number);
 if(!p||p.do_not_contact||p.outreach_consent!=='granted'||p.review_status!=='approved'||!/^[1-9]\d{7,14}$/.test(phone)||blocked.has(key(r)))continue;
 const g=groups.get(key(r))||[];
 g.push({...r,phone_number:phone,prospect_note:p.notes||''});
 groups.set(key(r),g);
}
return [...groups.values()].map(rows=>({json:{...rows[0],related_rows:rows}}));

const response=$input.first().json;
if(!response.messages?.[0]?.id||response.messages[0].message_status!=='accepted')throw new Error('Meta acceptance not confirmed; leave sending row for manual reconciliation.');
const group=$('Send one recipient at a time').item.json;
const at=new Date().toISOString(),messageId=response.messages[0].id;
return group.related_rows.map((r,i)=>({json:{id:r.id,prospect_id:r.prospect_id,expected_status:i===0?'sending':'approved_to_send',queue_status:i===0?'sent':'skipped_duplicate',sent_at:at,review_note:(r.review_note||'')+'\n'+(i===0?'Meta accepted intro':'Duplicate suppressed; intro accepted for campaign row '+group.id)+' at '+at+'; message ID: '+messageId+'. Delivery not confirmed.',prospect_note:(r.prospect_note||'')+'\nIntro accepted by Meta at '+at+'; message ID: '+messageId+'. Delivery not confirmed.'},pairedItem:{item:0}}));

const rows = $input.all()
  .map((item) => item.json)
  .filter((row) => Number.isInteger(row.id) && row.consent_status === 'granted' && row.queue_status === 'awaiting_final_approval' && row.phone_number)
  .sort((first, second) => String(first.business_name || '').localeCompare(String(second.business_name || '')));

const options = rows.map((row) => ({
  option: `${row.id} — ${row.business_name || 'Unnamed business'} (${row.phone_number})`,
}));

return [{
  json: {
    hasCampaignDrafts: rows.length > 0,
    formFields: [
      { fieldName: 'campaign_selection', fieldLabel: 'Choose a campaign draft', fieldType: 'dropdown', fieldOptions: { values: options }, requiredField: true },
      { fieldName: 'final_decision', fieldLabel: 'Final decision', fieldType: 'radio', fieldOptions: { values: [{ option: 'approved_to_send' }, { option: 'do_not_send' }] }, requiredField: true },
      { fieldName: 'notes', fieldLabel: 'Decision note', fieldType: 'textarea', placeholder: 'Optional reason for the decision', requiredField: false },
    ],
  },
}];

const selection = String($json.campaign_selection || '');
const match = selection.match(/^(\d+)\s+—/);

if (!match) {
  throw new Error('Please choose a valid campaign draft.');
}

if (!['approved_to_send', 'do_not_send'].includes($json.final_decision)) {
  throw new Error('Please choose a valid final decision.');
}

return {
  json: {
    ...$json,
    campaign_row_id: Number(match[1]),
  },
};
